package com.aistock.prediction.comparison;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;import java.util.concurrent.Semaphore;import static com.aistock.prediction.comparison.ComparisonRecords.*;
public final class ComparisonService {
 private final ComparisonRepository repository;private final ComparisonMarketClient market;private final Clock clock;private final ComparisonCalculator calculator;private final Semaphore permits;private final com.aistock.prediction.marketuse.ComparisonMarketUseOwner uses;
 public record Creation(Operation operation,boolean replayed){}
 public ComparisonService(ComparisonRepository repository,ComparisonMarketClient market,ObjectMapper mapper,Clock clock,int maxConcurrent){this(repository,market,mapper,clock,maxConcurrent,null);}
 public ComparisonService(ComparisonRepository repository,ComparisonMarketClient market,ObjectMapper mapper,Clock clock,int maxConcurrent,com.aistock.prediction.marketuse.ComparisonMarketUseOwner uses){this.uses=uses;if(maxConcurrent<1||maxConcurrent>32)throw new IllegalArgumentException("comparison concurrency must be 1..32");this.repository=repository;this.market=market;this.clock=clock;this.calculator=new ComparisonCalculator(clock);permits=new Semaphore(maxConcurrent);}
 public JsonNode options(List<String> ids,String period){return market.options(ids,period);}
 public Creation create(UUID owner,Input input){input.validate(clock);var old=repository.replay(owner,input,clock.instant());if(old!=null&&(!old.state().equals("RUNNING")||!old.expired()))return new Creation(old,true);if(!permits.tryAcquire())throw new BusinessException("COMPARISON_BUSY","当前对比计算较多，请稍后重试原请求",HttpStatus.TOO_MANY_REQUESTS);
  try{var claim=repository.claim(owner,input,clock.instant());if(!claim.execute())return new Creation(claim.operation(),true);try(var scope=uses==null?com.aistock.prediction.marketuse.MarketUseContext.empty():uses.acquire(owner,input,claim.generation())){long started=System.nanoTime();var sources=new ArrayList<JsonNode>();for(var id:input.evidenceIds()){if(System.nanoTime()-started>20_000_000_000L)throw ComparisonErrors.unavailable();sources.add(market.evidence(id));}if(System.nanoTime()-started>20_000_000_000L)throw ComparisonErrors.unavailable();var expected=com.aistock.prediction.marketuse.MarketUseContext.expectedVersions();if(!expected.isEmpty()&&!expected.equals(com.aistock.common.marketlifecycle.MarketLifecycleContract.versionSet(sources.stream().map(n->n.path("rawVersionId").asText()).toList())))throw com.aistock.prediction.marketuse.MarketUseClient.invalid();var result=calculator.calculate(input,sources);return new Creation(repository.complete(owner,input,claim.generation(),result,sources,clock.instant()),!claim.created());}catch(BusinessException e){repository.fail(owner,input,claim.generation(),e.code(),clock.instant());throw e;}catch(RuntimeException e){repository.fail(owner,input,claim.generation(),"COMPARISON_MARKET_UNAVAILABLE",clock.instant());throw ComparisonErrors.unavailable();}finally{if(uses!=null)uses.notifyCompleted(claim.generation());}}
  finally{permits.release();}}
 public Operation operation(UUID owner,UUID id){return repository.operation(owner,id,clock.instant());}public JsonNode get(UUID owner,UUID id){return repository.get(owner,id);}public ComparisonRepository.Page list(UUID owner,String before,String upper){return repository.list(owner,before,upper);}
}
